(() => {
'use strict';
const C=window.ACADEMY_CONTENT,E=window.AcademyEngines,KEY='digitalburj-canonical-academy-v2'+(window.ACADEMY_ACCOUNT_SCOPE?'-'+window.ACADEMY_ACCOUNT_SCOPE:'');
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const programmes=C.programmes,byId=Object.fromEntries(programmes.map(p=>[p.id,p])),missions=Object.fromEntries(programmes.flatMap(p=>p.modules.flatMap(mod=>mod.missions)).map(m=>[m.id,m]));
const initial=()=>({version:2,profile:{name:window.ACADEMY_PROFILE?.name||'',experience:'Zero knowledge',goal:window.ACADEMY_PROFILE?.goal||'DB-00',hours:window.ACADEMY_PROFILE?.hours||5,country:window.ACADEMY_PROFILE?.country||'',evidence:'',knowledge:0},drafts:{},attempts:[],failures:[],support:[],audit:[],contract:{},currentProgramme:byId[window.ACADEMY_PROFILE?.goal]?window.ACADEMY_PROFILE.goal:'DB-00',currentMission:byId[window.ACADEMY_PROFILE?.goal]?window.ACADEMY_PROFILE.goal+'-M01':'DB-00-M01'});
let S;try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');S=raw?.version===2&&raw.drafts&&Array.isArray(raw.attempts)?raw:initial()}catch{S=initial()}
const entryParams=new URLSearchParams(location.search);
let view='home',pid=byId[S.currentProgramme]?S.currentProgramme:'DB-00',mid=missions[S.currentMission]?S.currentMission:'DB-00-M01',stage='BRIEF',filter='All',search='',toolFilter='All';
let renderedContext=null;let pendingHTML=null;const human=s=>s.replaceAll('_',' '),now=()=>new Date().toISOString();
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));$('save-status').textContent='Saved in this browser'}catch{$('save-status').textContent='Storage full / export a backup';toast('Browser storage could not save this change. Export a backup before closing.')}}
function audit(action,record){S.audit.push({id:crypto.randomUUID?.()||String(Date.now())+Math.random(),time:now(),action,record});if(S.audit.length>1000)S.audit.shift();save()}
function toast(message){const el=$('toast');el.textContent=message;el.className='toast';setTimeout(()=>{el.className='';el.textContent=''},5500)}
function programmeMissions(p){return p?.modules?.flatMap(mod=>mod.missions)||[]}function currentProgramme(){return byId[pid]}function currentMission(){return missions[mid]}function completedMission(id){const d=S.drafts[id];return !!d&&C.stages.every(s=>d.stages?.[s])}function completedProgramme(id){return !!byId[id]&&programmeMissions(byId[id]).every(m=>completedMission(m.id))}function programmeCount(p){return programmeMissions(p).filter(m=>completedMission(m.id)).length}
function defaultCode(m){if(m.engine==='html')return '<!doctype html>\n<html lang="en"><head>\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Burj Café / Client page</title>\n<style>\nbody { font-family: system-ui; padding: 24px; }\n/* Add responsive layout and focus rules as needed. */\n</style></head><body>\n<!-- Build the requested client interface here. -->\n</body></html>';if(m.engine==='sql')return 'SELECT * FROM orders;';if(m.engine==='workflow')return JSON.stringify({steps:['record_result'],maxRetries:0,retryDelaySeconds:0,deadLetterOwner:''},null,2);return ''}
function draft(id=mid){if(!S.drafts[id]){const m=missions[id];S.drafts[id]={version:2,missionVersion:m.version,revision:1,fields:{},notes:{},code:defaultCode(m),stages:{},runs:[],actions:[],probes:[],fileLog:[],status:'Draft',hints:0,shipping:null,consent:'Private assessment preparation only'};}return S.drafts[id]}
function touch(d){d.revision++;d.lastRun=null;d.shipping=null;for(const k of ['TEST','SHIP','EVIDENCE'])delete d.stages[k];d.status='Draft';}
function btn(label,action,attrs='',primary=false){return `<button class="btn ${primary?'primary':''}" data-action="${action}" ${attrs}>${label}</button>`}
function input(key,label,value='',type='text',scope='field'){return `<div class="field"><label for="${scope}-${key}">${esc(label)}</label><input id="${scope}-${key}" data-${scope}="${key}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(value)}"></div>`}
function textarea(key,label,value='',scope='field',extra=''){return `<div class="field"><label for="${scope}-${key}">${esc(label)}</label><textarea id="${scope}-${key}" data-${scope}="${key}" ${extra}>${esc(value)}</textarea></div>`}
function select(key,label,options,value='',scope='field'){return `<div class="field"><label for="${scope}-${key}">${esc(label)}</label><select id="${scope}-${key}" data-${scope}="${key}"><option value="">Select</option>${options.map(v=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`}
function checkInput(key,label,value=false,scope='field'){return `<label class="checklabel"><input type="checkbox" data-${scope}="${key}" ${value?'checked':''}><span>${esc(label)}</span></label>`}
function table(rows){if(!rows?.length)return '<div class="empty">No rows returned.</div>';const columns=[...new Set(rows.flatMap(r=>Object.keys(r)))];return `<div class="tablewrap"><table><thead><tr>${columns.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${columns.map(k=>`<td>${esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function checks(result){return result?`<div class="workoutput">${result.checks.map(c=>`<div class="result"><b class="${c.pass?'pass':'fail'}">${c.pass?'PASS':'REVISE'} / ${esc(c.name)}</b>${c.detail?`<div class="caption">${esc(c.detail)}</div>`:''}</div>`).join('')}${result.requiresReview?'<div class="notice">These checks confirm evidence structure only. A qualified reviewer must evaluate professional quality.</div>':''}${result.output?.rows?table(result.output.rows):`<details><summary>Inspect actual output and trace</summary><pre>${esc(JSON.stringify(result.output,null,2))}</pre></details>`}</div>`:'<div class="notice">Run the work product to inspect the result. No result is assumed before execution.</div>'}
function services(){return window.AcademyService.shell()}
function render(){const active=document.activeElement,focusId=active?.id,focusAttrs=active?['data-action','data-id','data-step','data-stage','data-mentor','data-choice','data-view','data-service','data-tab'].filter(k=>active.hasAttribute?.(k)).map(k=>[k,active.getAttribute(k)]):[];const destination=view+'/'+(view==='workspace'?mid+'/'+stage:'');const moved=renderedContext!==null&&renderedContext!==destination;window.AcademyMentor?.stop();if(!byId[pid])pid='DB-00';if(!missions[mid]||!mid.startsWith(pid+'-'))mid=programmeMissions(byId[pid])[0].id;S.currentProgramme=pid;S.currentMission=mid;$('nav').innerHTML=[['home','Practice overview'],['services','Reviews, records & payments'],['catalog','Explore programmes'],['paths','Learning paths'],['workspace','Mission workspace'],['tools','Tool library'],['labs','Simulation labs'],['evidence','Evidence centre'],['failures','Failure Passport'],['assessment','Assessment centre'],['capability','Capability record'],['plan','Diagnostic & plan'],['support','Support preparation'],['operations','Curriculum & readiness']].map(([k,label])=>`<button class="nav ${view===k?'active':''}" data-view="${k}">${label}</button>`).join('');$('context-label').textContent=view==='workspace'?pid+' / '+mid+' / '+stage:programmes.length+' accessible programmes / 12-stage delivery';$('main').innerHTML=({home,catalog,paths,workspace,tools,labs,evidence,failures,assessment,capability,plan,support,operations,services}[view]||home)();if(view==='services')window.AcademyService.start();if(view==='workspace'&&['TRY','BUILD','FIX'].includes(stage)&&currentMission().engine==='html')runHTML(false);if(moved){const target=$('main').querySelector('h1,h2');if(target){target.tabIndex=-1;target.focus({preventScroll:true})}}else if(active&&!active.isConnected){const replacement=focusId?$(focusId):focusAttrs.length?[...document.querySelectorAll('button')].find(el=>focusAttrs.every(([k,v])=>el.getAttribute(k)===v)):null;if(replacement&&!replacement.disabled){replacement.focus({preventScroll:true})}else{const target=$('main').querySelector('.lesson-player h4')||$('main').querySelector('h1,h2');if(target){target.tabIndex=-1;target.focus({preventScroll:true})}}}renderedContext=destination;window.AcademyPractice?.update({view,pid,mid,stage});}
function openMission(id){mid=id;pid=id.split('-M')[0];view='workspace';const d=draft();stage=C.stages.find(s=>!d.stages[s])||'EVIDENCE';save();render()}
function pCard(p){const count=programmeCount(p);return `<article class="card programme"><div class="row between"><span class="tag">${p.id}</span><span class="caption">${p.pillar==='Technology'?'Technology':'Career practice'}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><div class="caption">4 missions / 12 preparation units / ${p.hours} planned hours</div><div class="bar"><span style="width:${count/4*100}%"></span></div><p class="caption">${count}/4 practice packs prepared · ${p.id==='DB-22'?'assessment-focused':'L1–L2 practice'}</p>${btn('Open programme','programme',`data-id="${p.id}"`)}</article>`}
function home(){const p=currentProgramme(),next=programmeMissions(p).find(m=>!completedMission(m.id))||programmeMissions(p)[0],done=Object.keys(S.drafts).filter(completedMission).length;return `<div class="row between"><div><div class="eyebrow">Practical work / evidence-based progression</div><h1>Professional Practice Workspace</h1><p class="muted">Apply your skills to real-world briefs, one carefully checked stage at a time.</p></div>${btn('Set your route','navigate','data-target="plan"')}</div><div class="cols"><section class="card"><div class="row between"><span class="tag">${p.id}</span><span class="caption">Professional mission / browser draft</span></div><h2 style="margin-top:15px">${esc(next.title)}</h2><p class="muted">${esc(next.scenario)}</p>${btn('Continue mission','open-mission',`data-id="${next.id}"`,true)}<div class="divider"></div><div class="legend">${C.stages.map(s=>`<span>${s}</span>`).join('<span class="muted">/</span>')}</div></section><section class="card"><h3>A clear path from first attempt to review</h3><p class="muted">If you are starting from zero, begin with DB-00. I’ll explain each step before you work in the tool. Make a small attempt, inspect what happened, correct it and keep the result. Later, a qualified reviewer can assess what you have demonstrated.</p>${btn('Explore your route','navigate','data-target="paths"')}<p class="caption" style="margin-top:16px">Practice completion, assessed submissions, independent verification and real workplace experience remain separate records.</p></section></div><div class="stats"><div class="card"><strong>${programmes.length}</strong><small>Accessible learning programmes</small></div><div class="card"><strong>${Object.keys(missions).length}</strong><small>Accessible missions</small></div><div class="card"><strong>${done}</strong><small>Practice evidence packs</small></div><div class="card"><strong>${S.failures.length}</strong><small>Failure investigations</small></div></div><h2>Choose one professional direction</h2><div class="grid">${programmes.slice(0,6).map(pCard).join('')}</div><details><summary>Supporting explanation / browser, frontend, backend and database</summary><p class="caption">Optional concept support. The assignments are the main learning environment.</p><video controls preload="none" style="width:100%;max-width:800px" src="https://sider-pub.s3.amazonaws.com/manim/manim-2a1bb485251f44d789feb29b2ef5651b.mp4"></video><p>The browser displays the frontend. A user action sends a request to the backend. The backend applies rules and reads or updates the database, then returns a result. Structure, appearance, behavior, access and stored records need separate checks.</p><a href="https://skillsail.com/create/digitalburj-academy-zero-to-first-website-acw13sopbxk4i" target="_blank" rel="noopener">Open the private supporting Skillsail module</a></details>`}
function catalog(){return `<div class="eyebrow">Learning programmes</div><h1>Technology & career practice.</h1><p class="muted">All 23 technology and 25 career programme codes from your operating handbook are represented. Each contains two modules, four practical missions, preparation, checks, evidence and a final assessment specification.</p><div class="toolbar"><div class="field"><label for="search">Find a programme or outcome</label><input id="search" value="${esc(search)}" placeholder="Programme, code, skill or topic"></div><div class="field"><label for="pillar">Pillar</label><select id="pillar">${['All','Technology','Professional Career'].map(v=>`<option ${v===filter?'selected':''}>${v}</option>`).join('')}</select></div></div><div id="programme-grid" class="grid">${filteredProgrammes().map(pCard).join('')||'<div class="empty">No matching programmes.</div>'}</div><div class="notice">Career programmes are country-neutral simulations pending qualified jurisdiction review. Advanced Professional Academy and International Workplace Readiness remain separate planning products, as specified in the PDF.</div>`}
function filteredProgrammes(){const q=search.toLowerCase();return programmes.filter(p=>(filter==='All'||p.pillar===filter)&&[p.id,p.title,p.summary,...p.outcomes].join(' ').toLowerCase().includes(q))}
const ROUTES=[{title:'AI-native full-stack delivery',goal:'DB-18',ids:['DB-00','DB-01','DB-02','DB-03','DB-04','DB-05','DB-07','DB-08','DB-09','DB-11','DB-12','DB-17','DB-06','DB-18','DB-22']},{title:'Business systems and automation',goal:'DB-13',ids:['DB-00','DB-01','DB-03','DB-05','DB-07','DB-12','DB-13','DB-21','DB-19']},{title:'Mobile product delivery',goal:'DB-14',ids:['DB-00','DB-01','DB-02','DB-03','DB-10','DB-14','DB-08','DB-22']},{title:'Content, visibility and client delivery',goal:'DB-16',ids:['DB-00','DB-01','DB-02','DB-15','DB-16','DB-20']},{title:'Professional workplace operations',goal:'PC-AD01',ids:['DB-00','DB-01','DB-21','PC-AD01','PC-AC01','PC-SA01','PC-CS01']}];
function paths(){return `<div class="eyebrow">Prerequisites / focus / progression</div><h1>Learning paths.</h1><p class="muted">A route combines prerequisites and domain practice. These are recommended practice routes; they do not create paid access, assessor approval or professional authority.</p><div class="grid">${ROUTES.map(r=>`<section class="card"><h3>${r.title}</h3><div>${r.ids.map(id=>`<div class="timeline-item"><strong>${id} / ${esc(byId[id]?.title||'Additional course access required')}</strong><span class="caption">${programmeCount(byId[id])}/4 practice packs prepared</span></div>`).join('')}</div>${btn('Select this direction','choose-route',`data-id="${r.goal}"`,true)}</section>`).join('')}</div><div class="divider"></div><h2>How capability grows</h2><div class="grid">${[['L1 / Guided basics','Follow prepared examples and produce a checked result.'],['L2 / Scenario capability','Complete a defined case, probe failures and provide a reproducible handover.'],['L3 / Published assessment','Requires a recorded academy assessment by an authorized evaluator.'],['L4 / Production delivery','Requires separate evidence of actual production delivery.'],['L5 / Repeated verified delivery','Requires repeated independently verified work.'],['Actual workplace experience','Requires genuine supervised or otherwise verified workplace activity.']].map(([h,b])=>`<div class="card"><h3>${h}</h3><p class="muted">${b}</p></div>`).join('')}</div>`}
function programmeHeader(p){return `<div class="row between"><div><div class="eyebrow">${p.id} / ${esc(p.pillar)}</div><h1>${esc(p.title)}</h1></div>${btn('All programmes','navigate','data-target="catalog"')}</div><p class="muted">${esc(p.summary)}</p><div class="row"><span class="tag">Version ${p.version}</span><span class="tag">${p.hours} planned hours</span><span class="tag">Practice preview</span></div>${p.prerequisites.length?`<p class="caption" style="margin-top:12px">Recommended prerequisites: ${p.prerequisites.map(id=>`${id} ${completedProgramme(id)?'(practice prepared)':'(not yet prepared)'}`).join(', ')}</p>`:''}${p.pillar!=='Technology'?'<div class="notice">Country-neutral fictional case rules. A qualified country reviewer must approve jurisdiction-sensitive instruction before professional release.</div>':''}`}
function workspace(){const p=currentProgramme(),m=currentMission(),d=draft();return `${programmeHeader(p)}<div class="mission-tabs">${programmeMissions(p).map((a,i)=>`<button class="mission-tab ${a.id===mid?'active':''}" data-action="open-mission" data-id="${a.id}"><span class="caption">MISSION 0${i+1} / ${completedMission(a.id)?'PACK PREPARED':'PRACTICE'}</span><br>${esc(a.title)}</button>`).join('')}</div><div class="workspace"><aside><div class="rail" aria-label="Mission stages">${C.stages.map((s,i)=>`<button class="stage ${s===stage?'active':''} ${d.stages[s]?'done':''}" data-stage="${s}"><b>${d.stages[s]?'✓':String(i+1).padStart(2,'0')}</b><span>${esc(window.AcademyMentor.stageNames[s])}<small>${s} / ${d.stages[s]?'Recorded':'Not recorded'}</small></span></button>`).join('')}</div><div class="sidemeta">${Object.keys(d.stages).length}/12 stages recorded<br>Revision ${d.revision}<br>${esc(m.taskType)}<br>Planned effort ${m.effortHours}h</div></aside><section class="stagebody"><div class="row between"><div><div class="eyebrow">${m.id} / ${stage}</div><h2>${esc(m.title)}</h2></div><span class="tag">${d.status==='Submitted'?'Submission pack prepared':'Draft'}</span></div><div class="brief notice">${esc(m.scenario)}</div>${window.AcademyMentor.render(m,d,stage)}${stageBody(m,d)}<div class="stagefooter"><div class="caption">${d.stages[stage]?'Stage recorded at '+new Date(d.stages[stage].time).toLocaleString():'Work evidence is needed before this stage can be recorded.'}</div>${btn(d.stages[stage]?'Continue to the next step':'Save this step and continue','complete-stage','',true)}</div></section></div>`}
function stageNote(label,value,placeholder=''){return textarea(stage,label,value||'','note',`placeholder="${esc(placeholder)}"`)}
function stageBody(m,d){const note=d.notes[stage]||'';if(stage==='BRIEF')return `<div class="cols"><section class="card"><h3>Define the actual work</h3><p>${esc(m.scenario)}</p>${stageNote('Your delivery objective and constraints',note,'State the required result, relevant source facts and the boundary of this task.')}${checkInput('briefAck','I have checked the scenario, required output and fictional-data constraints.',d.fields.briefAck)}</section><section class="card"><h3>Required work product</h3>${acceptanceList(m)}<h3>Evidence pack</h3><ul class="list">${m.evidenceRequirements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="notice">Keep learning completion, assessment approval and independent verification separate.</div></section></div>`;
if(stage==='LEARN')return `<section class="learning-content">${window.AcademyMentor.lesson(m,d)}<details><summary>Mission principle and reference notes</summary>${m.lessons.map((l,i)=>`<div class="step"><b>0${i+1}</b><div><h4>${esc(l.title)}</h4><p>${esc(l.body)}</p></div></div>`).join('')}<details><summary>Worked method and tool instructions</summary>${help(m)}</details></details>${stageNote('Explain the principle you will use',note,'Explain how the supplied rule or calculation applies to this case, and one assumption to check.')}${checkInput('learnAck','I have reviewed the preparation and know which operating rule I must verify.',d.fields.learnAck)}</section>`;
if(stage==='INVESTIGATE')return `<div class="cols"><section class="card"><h3>Inspect source records before changing them</h3>${source(m)}${btn('Record source inspection','inspect')}<p class="caption">${d.inspected?'Source inspection recorded at '+new Date(d.inspected).toLocaleTimeString():'Inspection has not been recorded.'}</p>${stageNote('Source facts, gaps and risks',note,'Identify which input is confirmed, what is missing, and a failure risk.')}</section><section class="card"><h3>Tool context</h3>${currentProgramme().tools.map(id=>{const t=C.tools.find(t=>t.id===id);return `<div class="result"><b>${esc(t.name)}</b><div class="caption">${esc(t.status)} / ${esc(t.limitations)}</div></div>`}).join('')}</section></div>`;
if(['TRY','BUILD','FIX'].includes(stage))return `<div class="notice">${stage==='TRY'?'Run a small attempt before committing to the complete result. An unsuccessful trial is useful evidence.':stage==='FIX'?'Correct the observed failure, then rerun the work product. Preserve what changed and why.':'Produce the requested result. Run it and compare the output with the brief.'}</div>${workbench(m,d)}${stage==='FIX'?stageNote('Correction and reasoning',note,'Describe the defect or unsafe assumption, the change and the successful retest.'):stage==='TRY'?stageNote('What the small attempt revealed',note,'Record what you tried, what happened and the next change.'):''}`;
if(stage==='BREAK')return `<section class="card"><h3>Test what happens when something goes wrong</h3><p class="muted">${failureDescription(m)}</p>${btn('Run the safe failure test','probe','',true)}${d.probes.length?`<div class="divider"></div>${d.probes.map(p=>`<div class="result"><b class="${p.rejected?'pass':'fail'}">${p.rejected?'Boundary held':'Failure exposed'} / ${esc(p.name)}</b><div class="caption">${new Date(p.time).toLocaleString()} / revision ${p.revision}</div><details><summary>Observed probe result</summary><pre>${esc(JSON.stringify(p.observed,null,2))}</pre></details></div>`).join('')}`:''}${stageNote('Failure interpretation',note,'Explain the observed failure or rejection, its cause, and what you will fix or verify next.')}</section>`;
if(stage==='TEST')return `<section class="card"><h3>Check that the result can be repeated</h3>${btn('Check my current work','run','',true)}${checks(d.lastRun)}${stageNote('Expected / actual / retest record',note,'State at least one normal result and one failure result, the expected outcome, observed outcome and retest.')}</section>`;
if(stage==='EXPLAIN')return `<section class="card"><h3>Explain the delivery decision</h3><p>${esc(m.principle)}</p>${stageNote('Decision, evidence, alternatives and limitations',note,'Explain why your approach fits the source facts, one alternative, and a limitation. Reference the run or probe results.')}</section>`;
if(stage==='DEFEND')return `<section class="card"><h3>Prepare for the reviewer’s questions</h3><p class="muted">This is a defence rehearsal. A qualified evaluator must separately assess your answers and the actual work.</p>${defenceQuestions(m).map((q,i)=>textarea('defence'+i,q,d.fields['defence'+i]||'')).join('')}</section>`;
if(stage==='SHIP')return `<section class="card"><h3>Package a usable handover</h3><p class="muted">Export the work product for its defined practice context. Packaging does not mean production release.</p>${btn('Export work product','ship','',true)}${d.shipping?`<p class="pass" style="margin-top:15px">Export prepared / ${esc(d.shipping.filename)} / revision ${d.shipping.revision}</p>`:''}${stageNote('Recipient, instructions and handover limits',note,'State who should use the result, how to reproduce it, and what is outside the delivered scope.')}</section>`;
return `<section class="card"><h3>Bring your review evidence together</h3><div class="row">${btn('Export this mission evidence','export-mission','',true)}${btn('Export complete portfolio','backup')}</div>${select('consent','Evidence sharing choice',['Private assessment preparation only','Prepared for a named reviewer / not sent'],d.consent,'meta')}${stageNote('Evidence provenance and consent purpose',note,'Identify source records, work product, tests, correction history and intended review purpose.')}${checkInput('evidenceAck','The evidence is fictional or explicitly consented, and no credentials or confidential records are included.',d.fields.evidenceAck)}<div class="notice">Recording EVIDENCE prepares a local submission pack. It does not send it to a reviewer, approve it, independently verify it or issue a credential.</div></section>`}
function acceptanceList(m){let items=m.fields?m.fields.map(f=>f.label):m.sections?m.sections:['Executable output matches the brief','Invalid or repeated action is handled','Observed normal and failure tests retained'];return '<ul class="list">'+items.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>'}
function source(m){if(m.engine==='sql')return table(E.tables.orders);if(m.engine==='api')return table(E.apiSeed().bookings);if(m.engine==='events')return table([{event:'EVT-1',revision:1,status:'created'},{event:'EVT-3',revision:3,status:'shipped'},{event:'EVT-2',revision:2,status:'packing'},{event:'EVT-3',revision:3,status:'shipped'}]);if(m.engine==='permissions')return `<p>Supplied policy: customer reads own records only; staff read and update assigned work; manager can read, update and assign; verifier reads assigned evidence but cannot update or assign bookings.</p>`;return `<p>${esc(m.scenario)}</p><div class="notice">Source: authored fictional case based on the PDF’s programme purpose. Actual external system records are not connected.</div>`}
function help(m){const guides={html:'Use semantic HTML with labels associated by for/id. Use width:100% and max-width for responsive layout. Example: <label for="email">Email</label><input id="email" type="email" required>. For behavior, attach a click or submit listener and update an aria-live result. Run preview and acceptance checks; inspect the actual output.',api:'An API request includes method, resource path, actor, body and optional request key. Example valid body: {"customerId":"alice","service":"repair","quantity":1}. GET reads a resource; POST creates one. Enable validation, ownership and duplicate protection, then inspect 200/201 success and 403/422 error cases.',sql:"Supported examples: SELECT * FROM orders; SELECT id, customer FROM orders WHERE status = 'pending'; SELECT SUM(quantity * unit_price) AS revenue FROM orders; SELECT id, quantity FROM orders WHERE status = 'pending' ORDER BY quantity DESC. This is a SELECT-subset trainer, not a connected PostgreSQL engine.",permissions:'Choose own, assigned, all or deny for every role/action. Use the supplied policy, then test cross-owner access and verifier mutation. A role label alone does not justify access to every record.',ledger:'For this receipt, debit Cash and credit Revenue with equal positive amounts. Use a stable event id and enable duplicate protection. Run the same event twice; the second should reuse the first posting. Unbalanced inputs should not alter balances.',events:'Enable monotonic revision handling and event-id duplicate detection. Process the complete event feed and inspect each applied or rejected decision. Revision 2 must not replace revision 3; the repeated EVT-3 must not be applied twice.',uploads:'Choose a fictional TXT, CSV or PDF at most 1 MB, or generate the safe fixtures. Run intake, inspect hash metadata and test unsupported/oversized rejection. Only metadata remains in the draft; production scanning and storage are not connected.',workflow:'The controlled workflow uses steps ["validate","deduplicate","human_approval","record_result"], a maxRetries value from 1 to 3, positive retryDelaySeconds and a named deadLetterOwner. A human approval state remains awaiting authorization; it never sends or purchases anything.',records:'Read each source fact. Enter the derived values or operating decisions. Numeric fields accept a number or arithmetic expression such as =3*12. Run checks, correct discrepancies, then complete the three operating actions in order. Every action retains a snapshot of the checked record.',document:'Prepare each required section as a usable professional output for the supplied brief. Include named sources, concrete actions, ownership, tests and limitations. Structure checks are not a quality assessment. Example: '+(m.example||'Use the stated case facts and retain verifiable evidence.')};return `<p>${esc(guides[m.engine])}</p><p class="caption">Hints support learning; they do not create an independent assessment result.</p>`}
function failureDescription(m){const map={records:'Omit a required operating value and verify the case checker refuses an incomplete record.',document:'Remove one required work-product section and verify the pack is flagged incomplete.',html:'Test the invalid field or interaction boundary in the isolated preview. A responsive failure probe tests deliberately wide content separately from your accepted layout.',api:'Inject quantity 0 and verify no valid booking is created.',sql:'Run a request against a missing table and verify it reports an error rather than an invented result.',permissions:'Test a different customer’s record and a verifier mutation against the supplied policy.',ledger:'Inject debit 100 / credit 90 and verify the ledger is unchanged.',events:'Inject the stale revision and repeated event, then inspect whether each is rejected.',uploads:'Run unsupported-file and oversized-file fixtures and verify neither is accepted.',workflow:'Inject an input with no order id and verify execution stops before any consequential step.'};return map[m.engine]}
function defenceQuestions(m){return ['Which source fact or observed result most strongly supports your decision?','What would fail if '+(m.engine==='records'?'a required source value were missing':m.engine==='api'?'ownership or duplicate checks were disabled':m.engine==='sql'?'the source table changed':m.engine==='ledger'?'the same event were posted twice':'the key constraint changed')+'?','What did you verify, and what still requires a real tool, qualified reviewer or workplace supervisor?']}
function workbench(m,d){let body='';if(m.engine==='records')body=`<div class="cols"><section class="card"><h3>Operating record desk</h3>${m.fields.map(f=>f.kind==='select'?select(f.key,f.label,f.options,d.fields[f.key]):input(f.key,f.label,d.fields[f.key]||'')).join('')}<div class="notice">Calculations support a number or = arithmetic expression. Decisions must follow the supplied case rules.</div>${btn('Run record checks','run','',true)}</section><section class="card"><h3>Controlled work actions</h3>${m.actions.map((label,i)=>`<div class="result">${btn(label,'case-action',`data-step="${i}" ${(d.actions.length!==i||!d.lastRun?.pass)?'disabled':''}`)}${d.actions[i]?'<div class="pass caption">Recorded / '+new Date(d.actions[i].time).toLocaleTimeString()+'</div>':''}</div>`).join('')}${checks(d.lastRun)}</section></div>`;
else if(m.engine==='document')body=`<section class="card"><h3>Professional work-product editor</h3>${m.sections.map((label,i)=>textarea('section'+i,label,d.fields['section'+i]||'')).join('')}${btn('Check evidence structure','run','',true)}${checks(d.lastRun)}</section>`;
else if(m.engine==='html')body=`<div class="cols"><section><label for="code" class="caption">Editable client HTML / CSS / JavaScript</label><textarea id="code" class="code" spellcheck="false" data-code="true">${esc(d.code)}</textarea><div class="row">${btn('Run preview','preview')}${btn('Run browser checks','run','',true)}${btn('Restore starter','reset-code','class="sm"')}</div><details><summary>Implementation guidance</summary>${help(m)}</details></section><section><div class="row between"><label class="caption" for="preview-width">Preview width</label><select id="preview-width" style="width:auto"><option value="100%">Responsive</option><option value="375px">375px mobile</option></select></div><iframe id="frame" class="preview" sandbox="allow-scripts" title="Isolated client page preview"></iframe><div class="notice">The preview runs learner scripts in an isolated origin. External requests and forms are blocked. No server environment is connected.</div></section></div>${checks(d.lastRun)}`;
else if(m.engine==='sql')body=`<div class="cols"><section class="card"><h3>Relational query desk</h3><label class="caption" for="code">One supported SELECT statement</label><textarea id="code" class="code" data-code="true">${esc(d.code)}</textarea>${btn('Execute query','run','',true)}<details><summary>Supported grammar and examples</summary>${help(m)}</details></section><section class="card"><h3>Source / orders</h3>${table(E.tables.orders)}<div class="notice">Bounded in-memory SELECT trainer. Actual PostgreSQL schemas, transactions, migrations and permissions require the external PostgreSQL sandbox.</div></section></div>${checks(d.lastRun)}`;
else if(m.engine==='api')body=`<div class="cols"><section class="card"><h3>Request console</h3>${select('method','Method',['GET','POST'],d.fields.method||'GET')}${input('path','Resource path',d.fields.path||'/bookings/BK-100')}${select('actor','Fictional actor',['alice','bob'],d.fields.actor||'alice')}${textarea('body','JSON request body',d.fields.body||'{}')}${input('requestKey','Idempotency key',d.fields.requestKey||'')}${btn('Send to fictional service','run','',true)}</section><section class="card"><h3>Service controls</h3>${checkInput('validation','Validate required fields and positive integer quantity',d.fields.validation)}${checkInput('ownership','Enforce customer record ownership',d.fields.ownership)}${checkInput('idempotency','Deduplicate stable request keys',d.fields.idempotency)}<details><summary>Request example and status rules</summary>${help(m)}</details><div class="notice">Requests execute against this mission’s fictional in-browser service. They do not call a live customer backend.</div>${checks(d.lastRun)}</section></div>`;
else if(m.engine==='permissions')body=`<section class="card"><h3>Role / action configuration</h3><p>${source(m)}</p><div class="tablewrap"><table><thead><tr><th>Role</th><th>Read</th><th>Update</th><th>Assign</th></tr></thead><tbody>${Object.keys(E.permissionExpected).map(role=>`<tr><td>${role}</td>${['read','update','assign'].map(action=>`<td><select aria-label="${role} ${action}" data-field="${role}_${action}"><option value="">Select</option>${['deny','own','assigned','all'].map(v=>`<option ${d.fields[role+'_'+action]===v?'selected':''}>${v}</option>`).join('')}</select></td>`).join('')}</tr>`).join('')}</tbody></table></div>${btn('Test access matrix','run','',true)}${checks(d.lastRun)}</section>`;
else if(m.engine==='ledger')body=`<div class="cols"><section class="card"><h3>Fictional transaction desk</h3>${input('eventId','Stable payment event id',d.fields.eventId||'')}${select('debitAccount','Debit account',['Cash','Revenue','Unknown'],d.fields.debitAccount)}${input('debit','Debit amount',d.fields.debit||'')}${select('creditAccount','Credit account',['Cash','Revenue','Unknown'],d.fields.creditAccount)}${input('credit','Credit amount',d.fields.credit||'')}${checkInput('deduplicate','Reuse existing posting for a repeated event id',d.fields.deduplicate)}<div class="row">${btn('Process posting','run','',true)}${btn('Reset fictional ledger','reset-runtime')}</div></section><section class="card"><h3>Posting evidence</h3>${checks(d.lastRun)}<details><summary>Posting and duplicate method</summary>${help(m)}</details></section></div>`;
else if(m.engine==='events')body=`<section class="card"><h3>Revision / event processing console</h3>${source(m)}${checkInput('monotonic','Accept only revisions newer than the current state',d.fields.monotonic)}${checkInput('deduplicate','Reject repeated event identifiers',d.fields.deduplicate)}${btn('Process the event feed','run','',true)}${checks(d.lastRun)}</section>`;
else if(m.engine==='workflow')body=`<div class="cols"><section class="card"><h3>Workflow configuration</h3><label class="caption" for="code">Editable execution policy / JSON</label><textarea class="code" id="code" data-code="true">${esc(d.code)}</textarea>${btn('Run controlled workflow','run','',true)}</section><section class="card"><h3>Execution boundaries</h3>${help(m)}${checks(d.lastRun)}</section></div>`;
else if(m.engine==='uploads')body=`<section class="card"><h3>File intake / provenance desk</h3><label class="caption" for="labfile">Select a fictional supported file</label><input id="labfile" type="file" accept=".txt,.csv,.pdf"><div class="row" style="margin-top:16px">${btn('Generate and process safe fixtures','file-fixtures','',true)}${btn('Run intake acceptance checks','run')}${btn('Clear local metadata','reset-files')}</div><div class="notice">TXT, CSV and PDF up to 1 MB. Hashes and metadata remain in this browser; original file bytes are not uploaded or retained. Production scanning and protected storage are separate.</div>${d.fileLog.length?table(d.fileLog.map(f=>({name:f.name,status:f.accepted?'Accepted':'Rejected',size:f.size||'',reason:f.reason||'',hash:f.sha256||''}))):''}${checks(d.lastRun)}</section>`;
return `${body}<div class="row between" style="margin-top:16px">${btn('Help me work through this','hint')}<span class="caption">Guidance steps opened: ${d.hints}</span></div>${d.hints?`<details open><summary>Guidance level ${d.hints}</summary>${d.hints===1?`<p>${esc(m.principle)}</p>`:d.hints===2?help(m):m.fields?'<ul class="list">'+m.fields.map(f=>`<li><b>${esc(f.label)}:</b> ${esc(f.why)}</li>`).join('')+'</ul>':help(m)}</details>`:''}`}
function gate(m,d,s){const n=String(d.notes[s]||'').trim().length,last=d.lastRun;const before=C.stages.slice(0,C.stages.indexOf(s));if(before.some(k=>!d.stages[k]))return 'Record the preceding stages first. You can inspect any stage, but progression must retain the full work sequence.';if(s==='BRIEF'&&(!d.fields.briefAck||n<40))return 'Check the brief and write a concrete delivery objective of at least 40 characters.';if(s==='LEARN'&&(!d.fields.learnAck||n<50))return 'Review the preparation and explain the applicable principle in at least 50 characters.';if(s==='INVESTIGATE'&&(!d.inspected||n<50))return 'Inspect the source and record confirmed facts, missing information and risks.';if(s==='TRY'&&(!d.runs.length||n<40))return 'Run a small attempt and record what it revealed.';if(s==='BUILD'&&(!last?.pass||last.revision!==d.revision))return 'Run the current work product and resolve the acceptance failures.';if(s==='BUILD'&&m.engine==='records'&&d.actions.length!==m.actions.length)return 'Complete the controlled operating actions after the checks pass.';if(s==='BREAK'&&(!d.probes.length||n<50))return 'Run a controlled failure probe and explain the observed result.';if(s==='FIX'&&(!last?.pass||last.revision!==d.revision||n<50||!d.runs.some(r=>r.time>=(d.probes.at(-1)?.time||''))))return 'Rerun the corrected work after the probe and explain the correction or verified control.';if(s==='TEST'&&(!last?.pass||last.revision!==d.revision||n<60))return 'Run the current acceptance suite and record expected, actual and failure-case results.';if(s==='EXPLAIN'&&n<100)return 'Explain your evidence-backed decision, alternative and limitation in at least 100 characters.';if(s==='DEFEND'&&[0,1,2].some(i=>String(d.fields['defence'+i]||'').trim().length<50))return 'Answer each defence question with specific evidence, at least 50 characters each.';if(s==='SHIP'&&(!d.shipping||d.shipping.revision!==d.revision||n<60))return 'Export the current work product and write a reproducible handover.';if(s==='EVIDENCE'&&(!d.fields.evidenceAck||n<60||!d.lastRun?.pass||d.lastRun.revision!==d.revision))return 'Confirm consent/data boundaries, identify provenance and retain a passing current result.';return null}
function completeStage(){const m=currentMission(),d=draft();if(stage==='EVIDENCE'&&S.attempts.some(a=>a.missionId===mid&&a.revision===d.revision)){view='evidence';render();toast('This revision already has a prepared submission pack.');return}const error=gate(m,d,stage);if(error){toast(error);return}d.stages[stage]={time:now(),revision:d.revision};audit('practice_stage_recorded',mid+'/'+stage);if(stage==='EVIDENCE'){d.status='Submitted';const attempt={id:crypto.randomUUID(),missionId:mid,programmeId:pid,version:m.version,time:now(),status:'Submitted',scope:'Local evidence preparation; not sent to an assessor',revision:d.revision,evidence:JSON.parse(JSON.stringify(d)),rubric:C.rubric};S.attempts.push(attempt);save();toast('Local submission pack prepared. Independent assessment and verification remain pending.');view='evidence'}else stage=C.stages[C.stages.indexOf(stage)+1];render()}
function pushRun(result){const d=draft();result.time=now();result.revision=d.revision;d.lastRun=result;d.runs.push({...result});if(d.runs.length>40)d.runs.shift();save();}
async function run(){const m=currentMission(),d=draft();if(m.engine==='html'){await runHTML(true);return}try{const result=E.run(m,d);pushRun(result);render();toast(result.pass?'Current local checks passed. Inspect and retain the result.':'Checks found a problem. Inspect the failed criteria and correct the work.')}catch(e){toast('The work environment could not run: '+e.message)}}
async function probe(){const m=currentMission(),d=draft();if(m.engine==='html'){await runHTML(true,true);return}const p=E.probe(m,d);recordProbe(p);render()}
function recordProbe(p){const d=draft();p.time=now();p.revision=d.revision;d.probes.push(p);if(d.probes.length>12)d.probes.shift();S.failures.push({id:crypto.randomUUID(),missionId:mid,time:p.time,name:p.name,boundaryHeld:p.rejected,observed:p.observed,correction:'',lesson:''});save();toast(p.rejected?'The failure boundary was rejected. Explain the control and retest it.':'The probe exposed a failure. Correct it and rerun the acceptance checks.')}
function htmlHarness(m,token,probeMode){const variant=m.variant;return `(() => { const check=(name,pass,detail='')=>({name,pass:!!pass,detail});const checks=[];const inputs=[...document.querySelectorAll('input')];const labeled=e=>!!e.id&&[...document.querySelectorAll('label')].some(l=>l.htmlFor===e.id&&l.textContent.trim());const style=[...document.querySelectorAll('style')].map(e=>e.textContent).join(' ');let output={variant:${JSON.stringify(variant)},probe:${probeMode}};try{if(${JSON.stringify(variant)}==='structure'){checks.push(check('One meaningful main heading',document.querySelectorAll('h1').length===1&&document.querySelector('h1').textContent.trim().length>2),check('Descriptive paragraph',[...document.querySelectorAll('p')].some(p=>p.textContent.trim().length>12)),check('Meaningful action button',[...document.querySelectorAll('button')].some(b=>b.textContent.trim().length>3)),check('Email has a visible associated label',inputs.some(e=>e.type==='email'&&labeled(e))));}else if(${JSON.stringify(variant)}==='responsive'){checks.push(check('Viewport configured',!!document.querySelector('meta[name="viewport"]')),check('Adaptive maximum-width rule',/max-width\\s*:/.test(style)&&/width\\s*:\\s*(100%|min\\(|clamp\\()/.test(style)),check('Focus-visible style',/:focus-visible/.test(style)),check('No horizontal overflow at preview width',document.documentElement.scrollWidth<=window.innerWidth+1));output.viewport=window.innerWidth;output.contentWidth=document.documentElement.scrollWidth;}else if(${JSON.stringify(variant)}==='interaction'){const b=document.querySelector('button'),live=document.querySelector('[aria-live]');const num=()=>{const v=(live?.textContent||'').match(/-?\\d+/g);return v?Number(v.at(-1)):NaN};const before=num();b?.click();b?.click();const after=num();checks.push(check('Action button exists',!!b),check('Live result exists',!!live),check('Two clicks increment by two',Number.isFinite(before)&&after===before+2));output={...output,before,after};}else{const form=document.querySelector('form'),name=inputs.find(e=>e.type==='text'&&e.required&&labeled(e)),email=inputs.find(e=>e.type==='email'&&e.required&&labeled(e)),live=document.querySelector('[aria-live]');checks.push(check('Form present',!!form),check('Required labeled name',!!name),check('Required labeled email',!!email),check('Live status region',!!live));if(form&&name&&email){name.value='';email.value='invalid';const rejected=!form.checkValidity();checks.push(check('Invalid inputs rejected by validity checks',rejected));name.value='Fictional Client';email.value='client@example.test';const before=live?.textContent||'';const ev=new Event('submit',{bubbles:true,cancelable:true});form.dispatchEvent(ev);checks.push(check('Submit navigation prevented',ev.defaultPrevented),check('Valid submit produces a status',!!live&&live.textContent.trim()!==before.trim()));output={...output,invalidRejected:rejected,status:live?.textContent};}}}catch(error){checks.push(check('Runtime behavior',false,error.message));output.error=error.message;}parent.postMessage({academyRun:true,token:${JSON.stringify(token)},checks,output},'*');})();`}
function buildPreview(code,harness=''){const doc=new DOMParser().parseFromString(code,'text/html');const csp=doc.createElement('meta');csp.httpEquiv='Content-Security-Policy';csp.content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; form-action 'none'; base-uri 'none';";doc.head.prepend(csp);if(harness){const s=doc.createElement('script');s.textContent="window.addEventListener('load',()=>setTimeout(()=>{"+harness+"},80));";doc.body.append(s)}return '<!doctype html>'+doc.documentElement.outerHTML}
async function runHTML(test=false,probeMode=false){const m=currentMission(),d=draft();let frame=$('frame');if(!frame){frame=document.createElement('iframe');frame.id='test-frame';frame.className='preview';frame.title='Isolated acceptance test preview';frame.sandbox='allow-scripts';$('main').append(frame)}const width=$('preview-width')?.value||((m.variant==='responsive')?'375px':'100%');frame.style.width=width;frame.style.maxWidth='100%';if(!test){frame.srcdoc=buildPreview(d.code);return}if(pendingHTML){toast('Wait for the current browser test to finish.');return}const token=crypto.randomUUID();const request={token,missionId:mid,revision:d.revision,frame,probeMode};pendingHTML=request;let code=d.code;if(probeMode&&m.variant==='structure')code='<!doctype html><html><body><h1>Incomplete fixture</h1><input type="email"></body></html>';if(probeMode&&m.variant==='responsive')code='<!doctype html><html><meta name="viewport" content="width=device-width"><style>body{width:1200px}</style><body>Overwide fixture</body></html>';if(probeMode&&m.variant==='interaction')code='<!doctype html><html><body><button>Order tea</button><p aria-live="polite">Orders: 0</p></body></html>';frame.srcdoc=buildPreview(code,htmlHarness(m,token,probeMode));setTimeout(()=>{if(pendingHTML?.token===token){pendingHTML=null;toast('The browser test did not return. Inspect the preview for a script error or nonterminating behavior.')}},5000)}
window.addEventListener('message',event=>{const p=pendingHTML,message=event.data;if(!p||event.source!==p.frame.contentWindow||!message?.academyRun||message.token!==p.token||!Array.isArray(message.checks))return;pendingHTML=null;if(mid!==p.missionId||draft().revision!==p.revision){toast('The test result was discarded because the work changed. Run it again.');return}const safe=message.checks.slice(0,12).map(c=>E.check(String(c.name),!!c.pass,String(c.detail||''))),result=E.result(safe,message.output);if(p.probeMode){const m=currentMission();let rejected=m.variant==='form'?safe.some(c=>c.name==='Invalid inputs rejected by validity checks'&&c.pass):!result.pass;recordProbe({name:failureDescription(m),rejected,observed:result})}else pushRun(result);render();toast(result.pass?'Browser acceptance checks passed. Retain the behavior evidence.':'Browser checks found a failure. Inspect the specific result.')});
function tools(){return `<div class="eyebrow">Practice environment / external requirements</div><h1>Dedicated tool library.</h1><p class="muted">Each tool shows its permitted use and actual availability. Local trainers are immediately usable. External services remain unconfigured until account, permissions, privacy and a safe test path are verified.</p><div class="pillbar">${['All',...new Set(C.tools.map(t=>t.category))].map(c=>`<button data-tool-filter="${esc(c)}" class="${toolFilter===c?'active':''}">${esc(c)}</button>`).join('')}</div><div class="grid">${C.tools.filter(t=>toolFilter==='All'||t.category===toolFilter).map(t=>`<article class="card"><span class="tag">${esc(t.category)}</span><h3 style="margin-top:14px">${esc(t.name)}</h3><p class="statusline">${esc(t.status)}</p><p class="muted">${esc(t.limitations)}</p><p class="caption">${esc(t.privacy)}</p>${programmes.some(p=>p.tools.includes(t.id))?btn('Find related practice','tool-practice',`data-id="${t.id}"`):'<span class="caption">Setup instructions required</span>'}</article>`).join('')}</div>`}
function labs(){const specs=[['Virtual Office','PC-AD01','Scheduling, correspondence, document control and escalation.'],['Accounting','PC-AC01','Invoices, reconciliation, variance and payment exceptions.'],['Freight Forwarding','PC-LG01','Cargo quantities, custody, delays and failed delivery.'],['Real Estate','PC-RE01','Verified listings, customer requirements and handover.'],['HR','PC-HR01','Candidate intake, onboarding and private record controls.'],['Banking Operations','PC-BF01','Service records, reconciliation and authority boundaries.'],['Insurance','PC-IN01','Intake evidence, amendments and qualified-review routing.'],['Document Processing','PC-DC01','Checklist completeness, conflicting references and corrections.'],['Procurement','PC-PC01','Supplier comparison, approvals and receiving discrepancies.'],['Customer Service','PC-CS01','Incident triage, safe evidence, updates and closure.']];return `<div class="eyebrow">Ten handbook simulation environments</div><h1>Professional operating labs.</h1><p class="muted">Each lab runs fictional records with checked decisions and an action trace. No lab connects to a government, bank, employer, healthcare provider or live customer system.</p><div class="grid">${specs.map(([title,id,scope])=>`<section class="card"><span class="tag">L1–L2 fictional practice</span><h3 style="margin-top:12px">${title}</h3><p>${scope}</p><p class="caption">4-case task queue · exceptions · escalation · evidence export · confirmed per-case reset</p>${btn('Open task queue','programme',`data-id="${id}"`,true)}<details><summary>Owner, review and jurisdiction</summary><p>Owner: Curriculum Operations. Qualified reviewer: not assigned. Last reviewed: pending. Country-neutral supplied rules only; professional country review required.</p></details></section>`).join('')}</div>`}
function evidence(){return `<div class="eyebrow">Work product / attempts / source / consent</div><h1>Evidence centre.</h1><div class="row">${btn('Export complete evidence backup','backup','',true)}${btn('Import a validated backup','import')}<input id="import-file" type="file" accept="application/json" hidden></div><div class="notice">Draft evidence stays in this browser. Open Reviews, records & payments to save a cloud backup or send a preserved attempt for review. Exporting alone does not submit it.</div><div class="card tablewrap"><table><thead><tr><th>Mission</th><th>Stage progress</th><th>Current result</th><th>Action</th></tr></thead><tbody>${Object.entries(S.drafts).length?Object.entries(S.drafts).map(([id,d])=>`<tr><td>${id}<br>${esc(missions[id]?.title)}</td><td>${Object.keys(d.stages).length}/12</td><td>${d.lastRun?.pass?'Local checks passed':'Draft / checks incomplete'}<br><small>Revision ${d.revision}</small></td><td>${btn('Open evidence','open-mission',`data-id="${id}"`)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">Begin a mission to create your first work record.</td></tr>'}</tbody></table></div><div class="divider"></div><h2>Submission and revision history</h2>${S.attempts.length?S.attempts.slice().reverse().map(a=>`<div class="card" style="margin-bottom:12px"><div class="row between"><div><b>${esc(a.missionId)}</b><p class="caption">${new Date(a.time).toLocaleString()} / revision ${a.revision} / ${esc(a.status)}</p></div>${btn('Export preserved attempt','export-attempt',`data-id="${a.id}"`)}</div><p>${esc(a.scope)}</p></div>`).join(''):'<div class="empty card">Complete all twelve stages to prepare a submission pack.</div>'}`}
function failures(){return `<div class="eyebrow">Failure → cause → correction → lesson</div><h1>Failure Passport.</h1><p class="muted">Record useful failures and boundary checks with their causes, corrections and lessons. This is a learning record, not a negative employment claim.</p>${S.failures.length?S.failures.slice().reverse().map(f=>`<section class="card" style="margin-bottom:15px"><span class="tag">${esc(f.missionId)}</span><h3 style="margin-top:12px">${esc(f.name)}</h3><p class="caption">${new Date(f.time).toLocaleString()} / ${f.boundaryHeld?'Boundary held':'Failure exposed'}</p><details><summary>Observed evidence</summary><pre>${esc(JSON.stringify(f.observed,null,2))}</pre></details><div class="field"><label for="correction-${f.id}">Cause and correction</label><textarea id="correction-${f.id}" data-failure="${f.id}" data-kind="correction">${esc(f.correction)}</textarea></div><div class="field"><label for="lesson-${f.id}">Lesson and preventive check</label><textarea id="lesson-${f.id}" data-failure="${f.id}" data-kind="lesson">${esc(f.lesson)}</textarea></div>${btn('Return to the mission','open-mission',`data-id="${f.missionId}"`)}</section>`).join(''):'<div class="empty card">Run BREAK in a mission to start a failure investigation.</div>'}`}
function assessment(){const target=byId[S.contract.programme||S.profile.goal]||byId['DB-00']||programmes[0],required=target.id==='DB-22'?target.prerequisites:[target.id],ready=required.every(completedProgramme);return `<div class="eyebrow">Readiness / contract / constrained work / defence</div><h1>Assessment centre.</h1><div class="cols"><section class="card"><h3>Assessment preparation contract</h3>${select('programme','Assessment route',programmes.map(p=>p.id),target.id,'contract')}${input('minutes','Planned build/demo window in minutes',S.contract.minutes||90,'number','contract')}${textarea('scope','Defined scope and changed constraint',S.contract.scope||'','contract')}${textarea('support','Permitted tools and support',S.contract.support||'','contract')}${checkInput('consent','I understand that scheduling, live evaluation and independent verification require configured services.',S.contract.consent,'contract')}${btn('Export assessment contract','export-contract','',true)}<div class="notice">Local timing is a planning aid, not proctoring. No assessor decision is created here.</div></section><section class="card"><h3>Readiness evidence</h3>${required.map(id=>`<div class="result"><b class="${completedProgramme(id)?'pass':'warning'}">${id} / ${esc(byId[id]?.title||'Additional course access required')}</b><p class="caption">${programmeCount(byId[id])}/4 practice packs prepared</p></div>`).join('')}<p class="statusline">${ready?'Local practice preparation complete; assessor eligibility review remains required.':'Prepare the prerequisite practice packs before assessment.'}</p>${btn('Open DB-22 challenge','programme','data-id="DB-22"')}<div class="divider"></div><h3>Independent review lifecycle</h3><p>${C.lifecycle.map(esc).join(' / ')}</p><p class="caption">Use Reviews, records & payments to send your work to the cloud. Review and verification require separately appointed qualified people.</p></section></div><div class="divider"></div><h2>Evaluation rubric</h2>${rubricTable()}<div class="notice">Suggested practice rubric threshold is 80/100 with no unresolved critical defect. Practice checks do not award a grade. The services desk supports qualified review, independent verification and verified mission skill records.</div>`}
function rubricTable(){return `<div class="card tablewrap"><table><thead><tr><th>Criterion</th><th>Weight</th><th>Evidence</th></tr></thead><tbody>${C.rubric.map(r=>`<tr><td>${esc(r.title)}</td><td>${r.weight}%</td><td>${esc({correctness:'Verified result against the source and brief',handover:'Usable work product and clear instructions',verification:'Normal and failure tests with expected/actual results',reasoning:'Evidence-backed decisions, alternatives and limitations',process:'Ownership, provenance, constraints and consent'}[r.id])}</td></tr>`).join('')}</tbody></table></div>`}
function capability(){return `<div class="eyebrow">Separate claims / honest scope</div><h1>Capability record.</h1><div class="grid">${[['Completion record',Object.keys(S.drafts).filter(completedMission).length+' locally prepared mission evidence packs. These are practice records.'],['Assessed submission','No authorized assessor result recorded. Export a submission pack for qualified evaluation.'],['Independently verified capability','No independent verification decision recorded. Reviewer and verifier must be separate where required.'],['Production delivery','No actual production-delivery claim is created by this learning workspace.'],['Repeated verified delivery','Requires repeated external delivery evidence and independent verification.'],['Actual workplace experience','Requires genuine supervised or otherwise verified workplace performance.']].map(([h,p])=>`<section class="card"><h3>${h}</h3><p class="muted">${p}</p></section>`).join('')}</div><div class="notice">No employment, visa, licence, accreditation, regulatory approval or guaranteed outcome is generated by a practice completion.</div><h2>Optional talent profile</h2><section class="card"><p>Private by default. A live profile, consented sharing and job-matching service are not connected.</p>${btn('Export private capability preparation','export-capability')}</section>`}
function plan(){const p=S.profile,route=ROUTES.find(r=>r.ids.includes(p.goal))||ROUTES[0];return `<div class="eyebrow">Diagnostic / prerequisites / realistic weekly practice</div><h1>Set your learning route.</h1><div class="cols"><section class="card">${input('name','Preferred name',p.name,'text','profile')}${select('experience','Current experience',['Zero knowledge','Some practical experience','Prior assessed experience'],p.experience,'profile')}${select('goal','Primary programme goal',programmes.map(p=>p.id),p.goal,'profile')}${input('hours','Weekly practice hours',p.hours,'number','profile')}${input('country','Country or target market for eventual qualified review',p.country,'text','profile')}${select('knowledge','Foundation self-check score / diagnostic input',['0','25','50','75','100'],String(p.knowledge),'profile')}${textarea('evidence','Prior evidence and demonstrated foundation knowledge',p.evidence,'profile')}${btn('Save diagnostic and route','save-plan','',true)}<div class="notice">A self-declared score does not approve a foundation bypass. Prior evidence needs a qualified reviewer; assessment, verification, safety and jurisdiction content are never bypassed.</div></section><section class="card"><h3>Recommended first action</h3><p>${p.experience==='Zero knowledge'||Number(p.knowledge)<75?'Start with DB-00 Digital Foundations. Complete controlled records, safe sharing and a reproducible handover before specializing.':'Review your prior evidence against DB-00, then complete the recommended prerequisites. No automatic bypass has been granted.'}</p><h3>Weekly practice rhythm</h3><p class="muted">Use approximately 20% preparation, 60% hands-on delivery and 20% testing and feedback. One programme is planned at 10 focused hours; at ${esc(p.hours)} hours/week, allow roughly ${Math.ceil(10/Math.max(1,Number(p.hours)||5))} weeks, then revise based on actual effort.</p><h3>${esc(route.title)}</h3><p>${route.ids.map(esc).join(' / ')}</p><p class="caption">These estimates describe the authored practice sequence. Advanced expertise requires multiple independent projects, qualified feedback and workplace or production transfer.</p></section></div>`}
function support(){return `<div class="eyebrow">Account / course / assessment / technical / accessibility / appeal</div><h1>Prepare a support request.</h1><div class="cols"><section class="card">${select('category','Support category',C.supportCategories,S.supportDraft?.category||'','support')}${textarea('message','Issue, expected outcome and evidence reference',S.supportDraft?.message||'','support')}${btn('Prepare support case','prepare-support','',true)}<div class="notice">This prepares a local request for export. It does not send a message or create a live support ticket.</div></section><section class="card"><h3>Prepared requests</h3>${S.support.length?S.support.slice().reverse().map(s=>`<div class="result"><b>${esc(s.category)} / ${esc(s.id)}</b><p>${esc(s.message)}</p><p class="caption">Prepared, not sent / ${new Date(s.time).toLocaleString()}</p>${btn('Export request','export-support',`data-id="${s.id}"`)}</div>`).join(''):'<div class="empty">No local request prepared.</div>'}<p class="caption">The live support lifecycle is Submitted / In Progress / Waiting for Learner / Resolved / Closed. Ownership, routing and service levels must be configured before live use.</p></section></div>`}
function validateCurriculum(){const errors=[],ids=new Set(),toolIds=new Set(C.tools.map(t=>t.id)),visit=new Set(),active=new Set();for(const p of programmes){if(ids.has(p.id))errors.push('Duplicate '+p.id);ids.add(p.id)}function walk(id){if(active.has(id)){errors.push('Circular prerequisite '+id);return}if(visit.has(id))return;active.add(id);for(const q of byId[id].prerequisites){if(!byId[q])errors.push('Broken prerequisite '+q);else walk(q)}active.delete(id);visit.add(id)}for(const p of programmes){walk(p.id);for(const id of p.tools)if(!toolIds.has(id))errors.push('Unknown tool '+id);if(!p.modules.length||p.modules.some(mod=>!mod.missions.length))errors.push('Empty module '+p.id);for(const m of programmeMissions(p)){if(!m.rubric?.length||!m.evidenceRequirements?.length)errors.push('Missing assessment evidence '+m.id);if(m.stages.join()!==C.stages.join())errors.push('Invalid stage order '+m.id);if(!m.lessons?.length)errors.push('Missing lessons '+m.id)}}return errors}
function operations(){const errors=validateCurriculum(),pc=programmes.filter(p=>p.pillar==='Professional Career');return `<div class="eyebrow">Canonical coverage / content governance / launch gates</div><h1>Curriculum & operating readiness.</h1><div class="stats"><div class="card"><strong>23</strong><small>Technology programmes</small></div><div class="card"><strong>25</strong><small>Career programmes</small></div><div class="card"><strong>192</strong><small>Domain missions</small></div><div class="card"><strong>${errors.length}</strong><small>Curriculum graph errors</small></div></div><div class="notice">The PDF defines a production target. This deployment implements practice content and local learning workflows; authoritative account, commerce, review and verification services are not configured.</div><div class="pillbar">${['coverage','readiness','products','roles','audit'].map(t=>`<button data-ops-tab="${t}" class="${(S.opsTab||'coverage')===t?'active':''}">${human(t)}</button>`).join('')}</div>${opsBody(S.opsTab||'coverage',errors,pc)}`}
function opsBody(tab,errors,pc){if(tab==='coverage')return `<div class="card tablewrap"><table><thead><tr><th>Programme</th><th>Modules / missions</th><th>Version / status</th><th>Dependencies / review</th></tr></thead><tbody>${programmes.map(p=>`<tr><td><b>${p.id}</b><br>${esc(p.title)}</td><td>2 modules / 4 missions<br>12 preparation units<br>12 stages per mission</td><td>${p.version}<br>${esc(p.status)}</td><td>${p.prerequisites.join(', ')||'Entry point'}<br><small>${p.pillar==='Technology'?'Qualified content review pending':'Country label and qualified jurisdiction review pending'}</small></td></tr>`).join('')}</tbody></table></div><details><summary>Schema, ownership and version controls</summary><p>Owner, version, revision date, audience, hours, prerequisites, skills, outcomes, tools, rubric, evidence, assessment and credential specification are recorded. Reviewer is unassigned; last-reviewed, effective and sunset dates remain empty until genuine approval. Authored learning units expand the supplied programme map; they are not quoted curriculum lessons from the PDF.</p><p>Content lifecycle: Draft / Review / Approved / Pilot / Live / Paused / Archived / Retired. Programme content here is authored practice, not approved Live commercial content.</p></details>${errors.length?`<pre>${esc(errors.join('\n'))}</pre>`:'<div class="notice">Duplicate ids, prerequisites, cycles, tool references, empty modules, missing lessons, rubric/evidence and stage-order checks passed.</div>'}`;
if(tab==='readiness')return `<div class="card tablewrap"><table><thead><tr><th>Capability</th><th>Current scope</th><th>Next production gate</th></tr></thead><tbody>${[['Curriculum','48 programmes, 192 practical missions and full stage definitions','Qualified instructional and domain review; accessibility and release approval'],['Practice tools','10 local work engines and 10 operating lab queues','Isolated external tool sandboxes and execution-service hardening'],['Learning state','Browser drafts plus signed-in cloud snapshots and revision conflict checks','Automatic sync, retention and recovery drills'],['Evidence','Private local metadata, work products and exports','Secure uploads, scanning, encrypted retention and restore testing'],['Identity','Private Sites access only','Learner accounts, MFA, secure sessions, roles and tenant enforcement'],['Payments and entitlements','Server checkout integration, signed payment messages and order history; products blocked','Merchant secrets, approved prices and terms, webhook ingress, refunds and entitlement release tests'],['Review and verification','Cloud submissions, qualified scope approvals, separate review and verification, appeals','Appoint real qualified people and grant their separate accounts access'],['Credentials','Private register with issue and withdrawal; verified mission required','Public consented verification, signing policy and programme-level credentials'],['Support and notifications','Cloud support, appeals, refund and adjustment requests with owner responses','Appointed support team, response times, email provider and delivery monitoring'],['Analytics and recovery','Local stage and action logs; export','Privacy-reviewed events, operational monitoring and recovery drills'],['Career release','Country-neutral simulations','Country labels, qualified review and applicable release evidence']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div><div class="notice">All real service gates remain separate. No frontend role selector, payment preview or completion flag is treated as a production authority.</div>`;
if(tab==='products')return `<section class="card"><h3>Commercial catalogue / no live checkout</h3><p>All 48 course product records are Draft. Price, currency, fees, refund terms, access duration and approvals are not configured. They are not purchasable.</p><p>International Workplace Readiness and Advanced Professional Academy are separate Planning products. Practice previews create no paid entitlement.</p>${input('coupon','Promotion preview code','')}${btn('Check proposed promotion','coupon')}<div id="coupon-result" class="notice">DigitalBurj100 is a proposed 100% discount only for eligible Live products. No product here is Live, so it cannot grant access.</div><details><summary>Product lifecycle and access separation</summary><p>Draft / Review / Pilot / Live / Paused / Archived. Account, payment, entitlement, progress, assessment, verification, credentials and talent visibility remain separate. Backend confirmation is required for every real commercial grant or revoke.</p></details></section>`;
if(tab==='roles')return `<section class="card"><h3>Role and separation specification</h3>${table([{role:'Learner',scope:'Own entitled learning and private evidence',restriction:'No review, verify or admin rights'},{role:'Reviewer',scope:'Assigned submissions and rubric review',restriction:'No self-review or verification of own approval'},{role:'Verifier',scope:'Independent assigned verification',restriction:'No review/approval/conflict on the same work'},{role:'Instructor',scope:'Instruction and support',restriction:'No unilateral assessment approval'},{role:'Finance',scope:'Commercial and reconciliation records',restriction:'No default learner evidence access'},{role:'Content Manager',scope:'Curriculum versions and release preparation',restriction:'No credential or payment authority'},{role:'Organisation Admin',scope:'Authorized tenant records',restriction:'No cross-tenant access'},{role:'Platform Admin',scope:'Approved configuration and services',restriction:'Privileged approval, MFA and audit required'},{role:'Auditor',scope:'Approved read-only control evidence',restriction:'No mutation'}])}<div class="notice">This is a permission specification, not a live role-management interface. Real user creation, invitations, suspension and role changes require identity and backend services.</div></section>`;
return `<section class="card"><h3>Local practice audit / not immutable server audit</h3>${table(S.audit.slice(-100).reverse().map(a=>({time:a.time,action:a.action,record:a.record})))}</section>`}
function download(filename,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportBackup(){download('DigitalBurj-Academy-v2-Evidence.json',{format:'DigitalBurjCanonicalAcademy',version:2,exportedAt:now(),state:S});toast('Complete evidence backup exported. It contains your drafts, notes and local records.')}
function ship(){const m=currentMission(),d=draft();if(!d.lastRun?.pass||d.lastRun.revision!==d.revision){toast('Run and pass the current work-product checks before packaging.');return}let filename=mid+'-r'+d.revision;if(m.engine==='html'){filename+='.html';download(filename,d.code,'text/html')}else if(m.engine==='sql'){filename+='.sql';download(filename,d.code,'text/plain')}else if(m.engine==='workflow'){filename+='-workflow.json';download(filename,d.code)}else{filename+='-deliverable.json';download(filename,{mission:m.id,brief:m.scenario,version:m.version,revision:d.revision,fields:d.fields,code:d.code,result:d.lastRun,actionTrace:d.actions,fileMetadata:d.fileLog,scope:'Fictional/local practice work product'})}d.shipping={filename,time:now(),revision:d.revision};audit('work_product_packaged',mid);render()}
async function fileFixtures(){const fixtures=[new File(['customer,count\nfictional-cafe,3\n'],'orders.csv',{type:'text/csv'}),new File(['safe blocked-type training fixture'],'blocked.exe',{type:'application/octet-stream'}),new File([new Uint8Array(1024*1024+1)],'oversized.txt',{type:'text/plain'})];for(const f of fixtures)await processFile(f,false);await run()}
async function processFile(file,rerender=true){try{if(!file)return;const missionId=mid,d=draft(),result=await E.validateFile(file);if(mid!==missionId){toast('The file result was discarded because the mission changed.');return}touch(d);d.fileLog.push(result);if(d.fileLog.length>20)d.fileLog.shift();save();if(rerender)render();toast(result.accepted?'Fictional file metadata and SHA-256 recorded.':'File rejected: '+result.reason)}catch(e){toast('File intake could not complete: '+e.message)}}
function sanitizedBackup(b){if(b?.format!=='DigitalBurjCanonicalAcademy'||b.version!==2||b.state?.version!==2||!b.state.drafts||typeof b.state.drafts!=='object'||Array.isArray(b.state.drafts))throw Error('This is not a v2 canonical academy backup. Original practice-library backups remain usable in the original library.');const n=initial(),s=b.state;if(s.profile&&typeof s.profile==='object'){for(const k of ['name','experience','country','evidence'])n.profile[k]=String(s.profile[k]||'').slice(0,5000);n.profile.goal=byId[s.profile.goal]?s.profile.goal:'DB-02';n.profile.hours=Math.max(1,Math.min(40,Number(s.profile.hours)||5));n.profile.knowledge=Math.max(0,Math.min(100,Number(s.profile.knowledge)||0))}for(const [id,v] of Object.entries(s.drafts)){if(!missions[id]||!v||typeof v!=='object')continue;const fields={};for(const [k,val] of Object.entries(v.fields||{})){if(/^[a-zA-Z0-9_]+$/.test(k))fields[k]=typeof val==='boolean'?val:String(val).slice(0,100000)}const notes={};for(const k of C.stages)notes[k]=String(v.notes?.[k]||'').slice(0,100000);n.drafts[id]={version:2,missionVersion:missions[id].version,revision:Math.max(1,Number(v.revision)||1),fields,notes,code:String(v.code||defaultCode(missions[id])).slice(0,200000),stages:{},runs:[],actions:[],probes:[],fileLog:[],status:'Draft',hints:Math.max(0,Math.min(3,Number(v.hints)||0)),shipping:null,consent:'Private assessment preparation only'};}n.currentProgramme=byId[s.currentProgramme]?s.currentProgramme:'DB-00';n.currentMission=missions[s.currentMission]?s.currentMission:'DB-00-M01';return n}
async function importFile(file){if(!file)return;try{if(file.size>15000000)throw Error('Backup exceeds the 15 MB limit.');const parsed=JSON.parse(await file.text()),next=sanitizedBackup(parsed);if(!confirm('Restore draft content from this backup? Export the current work first if needed. Imported stage completion and assessment claims will be cleared and must be rechecked.'))return;S=next;pid=S.currentProgramme;mid=S.currentMission;stage='BRIEF';view='evidence';audit('validated_backup_drafts_restored',String(Object.keys(S.drafts).length));render();toast('Draft content restored. Local stage evidence must be rerun; no assessment approval was imported.')}catch(e){toast(e.message)}}
async function action(name,el){const m=currentMission(),d=draft();if(name==='navigate'){view=el.dataset.target;render()}else if(name==='programme'){pid=el.dataset.id;openMission(programmeMissions(byId[pid]).find(m=>!completedMission(m.id))?.id||programmeMissions(byId[pid])[0].id)}else if(name==='open-mission')openMission(el.dataset.id);else if(name==='complete-stage')completeStage();else if(name==='run')await run();else if(name==='preview')await runHTML(false);else if(name==='probe')await probe();else if(name==='inspect'){d.inspected=now();audit('source_inspected',mid);render()}else if(name==='hint'){d.hints=Math.min(3,d.hints+1);save();render()}else if(name==='case-action'){const i=Number(el.dataset.step);if(!d.lastRun?.pass||d.lastRun.revision!==d.revision||d.actions.length!==i){toast('Run the current record checks and complete actions in order.');return}d.actions.push({action:m.actions[i],time:now(),revision:d.revision,record:{...d.fields}});audit('fictional_case_action',mid+'/'+i);render()}else if(name==='ship')ship();else if(name==='backup')exportBackup();else if(name==='export-mission')download(mid+'-evidence.json',{format:'DigitalBurjMissionEvidence',version:2,exportedAt:now(),programme:pid,mission:m,work:d,assessmentStatus:'Prepared only; independent review not connected'});else if(name==='export-attempt'){const a=S.attempts.find(a=>a.id===el.dataset.id);if(a)download(a.missionId+'-attempt-'+a.revision+'.json',a)}else if(name==='import')$('import-file').click();else if(name==='reset-code'){if(confirm('Replace this code draft with the starter? Export it first if needed.')){touch(d);d.code=defaultCode(m);save();render()}}else if(name==='reset-runtime'){if(confirm('Reset this fictional runtime? Your written evidence remains.')){touch(d);d.runtime=null;save();render()}}else if(name==='reset-files'){if(confirm('Clear only this mission’s local file metadata? Original files are not deleted.')){touch(d);d.fileLog=[];save();render()}}else if(name==='file-fixtures')await fileFixtures();else if(name==='tool-practice'){const p=programmes.find(p=>p.tools.includes(el.dataset.id));if(p)openMission(programmeMissions(p)[0].id)}else if(name==='choose-route'){S.profile.goal=el.dataset.id;view='plan';save();render()}else if(name==='save-plan'){S.profile.hours=Math.max(1,Math.min(40,Number(S.profile.hours)||5));audit('diagnostic_saved',S.profile.goal);toast('Diagnostic saved. Begin with the recommended prerequisite route.');render()}else if(name==='export-contract'){if(!S.contract.consent||String(S.contract.scope||'').length<50||String(S.contract.support||'').length<30){toast('Record scope, support boundaries and consent before exporting the contract.');return}download('DigitalBurj-Assessment-Contract.json',{...S.contract,preparedAt:now(),status:'Local preparation; not scheduled or evaluated'});}else if(name==='export-capability')download('DigitalBurj-Private-Capability-Preparation.json',{name:S.profile.name,preparedMissionPacks:Object.keys(S.drafts).filter(completedMission),assessedSubmissions:[],independentVerification:[],productionDelivery:[],workplaceExperience:[],sharing:'Private preparation only'});else if(name==='prepare-support'){const v=S.supportDraft||{};if(!C.supportCategories.includes(v.category)||String(v.message||'').trim().length<50){toast('Select a category and describe the issue with at least 50 characters.');return}const record={...v,id:'LOCAL-'+Date.now(),time:now(),status:'Prepared / not sent'};S.support.push(record);S.supportDraft={};audit('support_request_prepared',record.id);render()}else if(name==='export-support'){const r=S.support.find(r=>r.id===el.dataset.id);if(r)download(r.id+'.json',r)}else if(name==='coupon'){const code=String($('field-coupon')?.value||'').trim();$('coupon-result').textContent=code.toLowerCase()==='digitalburj100'?'Not eligible: there are no approved Live products. No redemption, payment or entitlement was created.':'Invalid proposed code. No redemption, payment or entitlement was created.'}}
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;if(el.dataset.view){view=el.dataset.view;render()}else if(el.dataset.stage){stage=el.dataset.stage;render()}else if(el.dataset.action){if(el.disabled)return;try{await action(el.dataset.action,el)}catch(e){toast('This action could not complete: '+e.message)}}else if(el.dataset.toolFilter){toolFilter=el.dataset.toolFilter;render()}else if(el.dataset.opsTab){S.opsTab=el.dataset.opsTab;render()}});
document.addEventListener('input',event=>{const el=event.target,d=draft(),v=el.type==='checkbox'?el.checked:el.value;if(el.dataset.field){const key=el.dataset.field;if(key==='coupon')return;const isPreparation=['briefAck','learnAck','evidenceAck'].includes(key)||key.startsWith('defence');if(!isPreparation){touch(d);d.actions=[]}d.fields[key]=v;save();if(!isPreparation){document.querySelectorAll('[data-step]').forEach(b=>b.disabled=true)}}else if(el.dataset.code){touch(d);d.code=String(v);save()}else if(el.dataset.note){d.notes[el.dataset.note]=String(v);delete d.stages[el.dataset.note];d.status='Draft';save()}else if(el.dataset.meta){d[el.dataset.meta]=v;save()}else if(el.dataset.profile){S.profile[el.dataset.profile]=v;save()}else if(el.dataset.contract){S.contract[el.dataset.contract]=v;save()}else if(el.dataset.support){S.supportDraft=S.supportDraft||{};S.supportDraft[el.dataset.support]=v;save()}else if(el.dataset.failure){const f=S.failures.find(f=>f.id===el.dataset.failure);if(f){f[el.dataset.kind]=String(v);save()}}else if(el.id==='search'){search=el.value;$('programme-grid').innerHTML=filteredProgrammes().map(pCard).join('')||'<div class="empty">No matching programmes.</div>'}});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='pillar'){filter=el.value;render()}else if(el.id==='preview-width'){const f=$('frame');if(f){f.style.width=el.value;f.style.maxWidth='100%'}}else if(el.id==='labfile')await processFile(el.files[0]);else if(el.id==='import-file')await importFile(el.files[0]);});
$('backup').onclick=exportBackup;
if(byId[entryParams.get('programme')]){pid=entryParams.get('programme');mid=programmeMissions(byId[pid])[0].id;view='workspace';}else if(['home','catalog','paths','workspace','tools','labs','evidence','failures','assessment','capability','plan','support','operations','services'].includes(entryParams.get('view')))view=entryParams.get('view');
if(view==='workspace'){const requestedMission=entryParams.get('mission');if(missions[requestedMission]&&requestedMission.startsWith(pid+'-'))mid=requestedMission;if(C.stages.includes(entryParams.get('stage')))stage=entryParams.get('stage');}
render();
window.AcademyMentorBridge={save,render,openStage:s=>{stage=s;render()}};
window.AcademyCloud={snapshot:()=>JSON.parse(JSON.stringify(S)),attempts:()=>JSON.parse(JSON.stringify(S.attempts)),restore:b=>{S=sanitizedBackup({format:"DigitalBurjCanonicalAcademy",version:2,state:b});pid=S.currentProgramme;mid=S.currentMission;save()}};
window.AcademyQA={content:C,engines:E,validateCurriculum,gate,sanitizedBackup};
})();
